import { useEffect, useState } from 'react';

/** 财报 PDF 在 iframe 里的加载状态 */
export type PdfFrameStatus = 'loading' | 'ready' | 'failed';

/**
 * 财报 PDF 的加载超时（毫秒）。
 * 跨域 iframe 读不到内容，404 / X-Frame-Options / 签名过期都可能照常触发 onLoad，
 * 因此「失败」只能用超时兜底。
 */
export const PDF_FRAME_TIMEOUT_MS = 20000;

export interface PdfFrame {
  status: PdfFrameStatus;
  /** 作为 iframe 的 key：重试时自增，强制重新挂载（同 URL 的失败加载不会自己重来） */
  frameKey: number;
  onFrameLoad: () => void;
  retry: () => void;
}

/**
 * 财报 PDF（iframe）的加载状态机。
 * src 变化（切换财报年度）或重试后回到加载中，并重新计时。
 */
export function usePdfFrame(src: string): PdfFrame {
  const [status, setStatus] = useState<PdfFrameStatus>('loading');
  const [attempt, setAttempt] = useState(0);

  useEffect(() => {
    setStatus('loading');
    const timer = setTimeout(
      () =>
        setStatus((current) => (current === 'loading' ? 'failed' : current)),
      PDF_FRAME_TIMEOUT_MS,
    );
    return () => clearTimeout(timer);
  }, [src, attempt]);

  return {
    status,
    frameKey: attempt,
    onFrameLoad: () => setStatus('ready'),
    retry: () => {
      setStatus('loading');
      setAttempt((current) => current + 1);
    },
  };
}

/* learn-c · 组件行为冒烟测试
