// ---------- 最小 DOM ----------
function El(tag, attrs = {}) {
  const el = {
    tagName: tag, attrs, listeners: {}, children: [], textContent: '', innerHTML: '',
    disabled: false, hidden: false, className: '',
  };
  el.classList = {
    _s: new Set(),
    add(...c) { c.forEach(x => el.classList._s.add(x)); },
    contains(c) { return el.classList._s.has(c); },
  };
  el.getAttribute = n => (n in attrs ? attrs[n] : null);
  el.setAttribute = (n, v) => { attrs[n] = v; };
  el.appendChild = c => { el.children.push(c); return c; };
  el.addEventListener = (t, fn) => { (el.listeners[t] ||= []).push(fn); };
  el.click = () => (el.listeners.click || []).forEach(fn => fn());
  return el;
}

const quizHtml = fs.readFileSync(path.join(root, 'lessons', '0001-compile-link-run.html'), 'utf8');
const sections = [...quizHtml.matchAll(/<section class="quiz"([\s\S]*?)<\/section>/g)].map(m => m[1]);
if (!sections.length) { console.error('FAIL: 没找到任何 .quiz'); process.exit(1); }

const quizzes = sections.map(body => {
  const attr = n => (body.match(new RegExp(n + '="([^"]*)"')) || [])[1];
  const quiz = El('section', { 'data-id': attr('data-id'), 'data-answer': attr('data-answer'), 'data-explain': attr('data-explain') });
  const optRe = /data-key="([^"]*)"((?:\s+data-why="[^"]*")?)\s*>([^<]*)<\/button>/g;
  const opts = [...body.matchAll(optRe)].map(m => {
    const why = (m[2].match(/data-why="([^"]*)"/) || [])[1];
    const o = El('button', Object.assign({ 'data-key': m[1] }, why ? { 'data-why': why } : {}));
    o.textContent = m[3];
    return o;
  });
  quiz.querySelectorAll = () => opts;
  quiz.querySelector = sel => (sel === '.quiz__feedback' ? (quiz._fb ||= El('div')) : null);
  quiz._opts = opts;
  return quiz;
});

