// current stripBackground cost (memoized hit vs miss)
const stripCache = new Map();
const uncached = (text) => text.replace(/\x1b\[([0-9;]*)m/g, (_m, params) => {
  const parts = params.split(";").filter((p) => p !== "");
  if (parts.length === 0) return "\x1b[m";
  const kept = [];
  for (let i = 0; i < parts.length; i += 1) {
    const code = Number(parts[i]);
    if (code === 48) { if (parts[i + 1] === "5") i += 2; else if (parts[i + 1] === "2") i += 4; else i += 1; continue; }
    if (code === 49) continue;
    if (code >= 40 && code <= 47) continue;
    kept.push(parts[i]);
  }
  return kept.length > 0 ? `\x1b[${kept.join(";")}m` : "";
});
