// pi session jsonl -> fast-jev-compaction Message[]
import { readFileSync } from "node:fs";

const blocks = (c) =>
  Array.isArray(c) ? c : typeof c === "string" ? [{ type: "text", text: c }] : [];
const textOf = (bs) =>
  bs.filter((b) => b?.type === "text").map((b) => b.text ?? "").join("");

/** Active branch (last entry -> root), with the last compaction applied. */
export function activeEntries(file) {
  const entries = readFileSync(file, "utf8")
    .split("\n")
    .filter((l) => l.trim())
    .map((l) => JSON.parse(l));
  const byId = new Map(entries.filter((e) => e.id).map((e) => [e.id, e]));
  const chain = [];
  const seen = new Set();
  let cur = entries[entries.length - 1];
  while (cur && !seen.has(cur.id)) {
    seen.add(cur.id);
    chain.push(cur);
    cur = byId.get(cur.parentId);
  }
  chain.reverse();
  let last = -1;
  chain.forEach((e, i) => {
    if (e.type === "compaction") last = i;
  });
  if (last < 0) return { chain, summary: "" };
  const start = chain.findIndex(
    (e) => e.id === chain[last].firstKeptEntryId,
  );
  return {
    chain: chain.slice(start < 0 ? chain.length : start),
    summary: chain[last].summary ?? "",
  };
}

export function toMessages(chain, summary) {
  const messages = [];
  if (summary) messages.push({ role: "user", text: `[conversation so far, summarized]\n${summary}`, toolUses: [] });
  for (const entry of chain) {
    const m = entry.message;
    if (!m) continue;
    const bs = blocks(m.content);
    if (m.role === "user") {
      messages.push({ role: "user", text: textOf(bs), toolUses: [] });
    } else if (m.role === "assistant") {
      messages.push({
        role: "assistant",
        text: textOf(bs),
        toolUses: bs
          .filter((b) => b?.type === "toolCall")
          .map((b) => ({
            tool_use_id: b.id,
            tool: b.name,
            input: b.arguments ?? {},
            ...(typeof b.text === "string" ? { text: b.text } : {}),
            ...(b.isError ? { isError: true } : {}),
          })),
      });
    } else if (m.role === "toolResult") {
      messages.push({
        role: "user",
        text: "",
        toolUses: [],
        toolResults: [
          {
            tool_use_id: m.toolCallId,
            text: textOf(bs),
            ...(m.isError ? { isError: true } : {}),
          },
        ],
      });
    }
  }
  return messages.filter(
    (m) => m.text.trim().length > 0 || m.toolUses.length > 0 || m.toolResults?.length,
  );
}

